	 ('d858aa14-8352-4499-b6f8-cdb3e1d39715','Nike Air Max Verse','{"benefits":[{"header":"Power and Comfort in the Paint","body":["The Nike Air Max Verse is designed for basketball players who demand cushioning and support for powerful moves and explosive plays. Dominate the court with confidence."]},{"header":"Maximum Cushioning","body":["Full-length Max Air cushioning provides exceptional impact absorption and responsiveness, reducing stress on your joints and keeping you fresh throughout the game."]},{"header":"Secure and Supportive Fit","body":["The supportive upper and secure lacing system lock your foot in place, providing stability and control for quick cuts, pivots, and jumps."]}],"product_details":[{"header":"Product Details","body":["Synthetic leather and mesh upper","Full-length Max Air cushioning","Durable rubber outsole with herringbone pattern","Padded collar and tongue","Style: CD4564-001 (Example)"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/cd8dbea1-655a-4f68-a8bf-6892e55c72df/NIKE+AIR+MAX+VERSE.png','490.50','2025-03-05 15:26:25.61053','2025-03-05 15:26:25.61053','running','men'),
	 ('a045c2fd-0044-49d2-8612-7c12eab26509','Nike Zoom Vomero Roam','{"benefits":[{"header":"Retro Style, Modern Performance","body":["The Nike Zoom Vomero Roam combines classic Vomero aesthetics with modern performance technology, creating a versatile shoe for everyday wear and light activities. Blending style with function."]},{"header":"Responsive Cushioning","body":["Zoom Air cushioning in the forefoot provides a responsive and springy feel, enhancing comfort and energy return with every step."]},{"header":"Durable and Versatile","body":["The durable upper and rugged outsole offer protection and traction on various surfaces, making it suitable for both urban adventures and outdoor explorations."]}],"product_details":[{"header":"Product Details","body":["Durable upper with overlays","Zoom Air cushioning in the forefoot","Rugged rubber outsole","Padded collar and tongue","Style: FD9923-001 (Example)"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/aa5157d4-a355-4ac0-8871-0c8d05cfabb3/NIKE+ZOOM+VOMERO+ROAM.png','473.44','2025-03-05 15:26:25.611155','2025-03-05 15:26:25.611155','lifestyle','men'),
	 ('aeec9eba-dffa-46f3-8407-c0e5107d7ce2','Nike Interact Run EasyOn','{"benefits":[{"header":"Effortless Comfort, Easy On and Off","body":["The Nike Interact Run EasyOn features a streamlined design and innovative EasyOn technology, making it incredibly easy to slip on and off, perfect for busy lifestyles."]},{"header":"Responsive and Cushioned Ride","body":["Experience a smooth and comfortable ride with the lightweight cushioning that absorbs impact and provides energy return for all-day wear."]},{"header":"Secure and Supportive","body":["The breathable upper and supportive design ensure a secure and comfortable fit, allowing you to move with confidence throughout your day."]}],"product_details":[{"header":"Product Details","body":["Breathable upper with EasyOn technology","Lightweight cushioning","Durable rubber outsole","Padded collar for added comfort","Style: DR3160-001 (Example)"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/b13032d1-d2ad-43a0-87a1-6b72cec0e8da/NIKE+INTERACT+RUN+EASYON.png','364.25','2025-03-05 15:26:25.611797','2025-03-05 15:26:25.611797','football','men'),
	 ('1565684a-6a4f-4a54-9137-fdfc0d164123','Nike Interact Run EasyOn','{"benefits":[{"header":"Effortless Comfort, Easy On and Off","body":["The Nike Interact Run EasyOn features a streamlined design and innovative EasyOn technology, making it incredibly easy to slip on and off, perfect for busy lifestyles."]},{"header":"Responsive and Cushioned Ride","body":["Experience a smooth and comfortable ride with the lightweight cushioning that absorbs impact and provides energy return for all-day wear."]},{"header":"Secure and Supportive","body":["The breathable upper and supportive design ensure a secure and comfortable fit, allowing you to move with confidence throughout your day."]}],"product_details":[{"header":"Product Details","body":["Breathable upper with EasyOn technology","Lightweight cushioning","Durable rubber outsole","Padded collar for added comfort","Style: DR3160-400 (Example)"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/fe713445-6294-40a8-90e0-80b97a7ddeab/NIKE+INTERACT+RUN+EASYON.png','324.12','2025-03-05 15:26:25.612518','2025-03-05 15:26:25.612518','football','men');
