	 ('93d8dd92-4328-44ba-87e4-bcbc2c1a41e3','NikeCourt Royale 2 Next Nature','{"benefits":[{"header":"Classic Style, Sustainable Design","body":["The NikeCourt Royale 2 Next Nature combines the iconic look of a classic tennis shoe with a commitment to sustainability, using recycled materials in its construction."]},{"header":"All-Day Comfort","body":["With a cushioned insole and padded collar, these shoes provide all-day comfort, whether you''re on the court or running errands."]},{"header":"Durable Traction","body":["The durable rubber outsole offers reliable traction on a variety of surfaces, ensuring stability and support with every step."]}],"product_details":[{"header":"Product details","body":["Upper made with recycled materials","Classic tennis shoe silhouette","Padded collar for added comfort","Durable rubber outsole","Colour Shown: White/Pink Oxford/Coconut Milk","Style: DH3159-103"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/3134fd9b-b486-4ebc-be50-5d16c8c0c8f4/NIKE+COURT+ROYALE+2+NN.png','407.65','2025-03-05 15:26:25.706351','2025-03-05 15:26:25.706351','gym_and_training','men'),
	 ('65382509-54df-4a1b-b6a3-ee97a99f6cd9','Nike Cortez Leather','{"benefits":[{"header":"Timeless Style","body":["The Nike Cortez Leather embodies a timeless design that has remained a fashion staple for decades, offering a classic look that complements any outfit."]},{"header":"Comfortable and Durable","body":["Crafted with a premium leather upper and a cushioned midsole, these shoes provide exceptional comfort and long-lasting durability for everyday wear."]},{"header":"Iconic Traction","body":["The herringbone-patterned rubber outsole delivers reliable traction on various surfaces, ensuring stability and grip in any situation."]}],"product_details":[{"header":"Product details","body":["Full-grain leather upper","EVA midsole for lightweight cushioning","Herringbone-patterned rubber outsole","Colour Shown: White/Black","Style: 807472-101"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/464ab3ac-0dc0-4fd0-84bd-eae123a2db18/NIKE+CORTEZ.png','243.66','2025-03-05 15:26:25.707162','2025-03-05 15:26:25.707162','basketball','men'),
	 ('52440b0f-ec9e-4342-bf79-d52d84ce9271','Nike SB Malor','{"benefits":[{"header":"Durable Skateboarding Performance","body":["The Nike SB Malor is designed for skateboarding, offering the durability and grip needed for the demands of the sport."]},{"header":"Comfort and Board Feel","body":["Featuring a durable upper, cushioned insole, and grippy outsole, the SB Malor provides both comfort and excellent board feel for a confident skateboarding experience."]}],"product_details":[{"header":"Product details","body":["Durable suede upper","Cushioned insole","Grippy rubber outsole","Reinforced stitching","Style: DM3493-001"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/9cdc0994-92fc-481c-af17-1afb48e1c118/NIKE+SB+MALOR.png','454.96','2025-03-05 16:04:47.8085','2025-03-05 16:04:47.8085','lifestyle','women');
