	 ('1edb023c-708f-47ec-987a-5fed7e1df85b','Nike Mercurial Vapor 16 Academy By You','{"benefits":[{"header":"Precision Touch","body":["The upper is designed to enhance your touch on the ball, providing precise control for dribbling, passing, and shooting."]},{"header":"Dynamic Movement","body":["Designed for quick cuts and acceleration, the outsole delivers optimal traction on firm-ground surfaces."]}],"product_details":[{"header":"Product Details","body":["Firm-ground (FG) cleats for use on short-grass fields","Synthetic upper for enhanced ball control","Conical studs for multidirectional traction","Cushioned insole for comfort","By You customization options available"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/31c3080d-5343-4a75-af70-e4603bae8046/ZM+VAPOR+16+ACADEMY+FG+NBY.png','355.60','2025-03-05 16:04:48.212846','2025-03-05 16:04:48.212846','football','women'),
	 ('baa63a03-a026-4132-a497-108cbf06eaee','Nike Mercurial Vapor 16 Elite By You','{"benefits":[{"header":"Explosive Speed","body":["Designed for elite-level performance, these cleats provide the responsiveness and traction needed for explosive acceleration and speed on the field."]},{"header":"Enhanced Ball Control","body":["The innovative upper material offers exceptional ball feel, allowing for precise control and confident dribbling."]},{"header":"Optimal Traction","body":["AG-PRO (Artificial Grass) soleplate provides excellent traction and stability on artificial turf surfaces."]}],"product_details":[{"header":"Product Details","body":["AG-PRO (Artificial Grass) cleats for use on artificial turf fields","Premium upper material for superior ball feel","Dynamic Fit collar for a secure, sock-like fit","Cushioned insole for maximum comfort","By You customization options available"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/a09a01cc-2fdd-48d3-bb07-c7814338b1c9/ZM+VAPOR+16+ELITE+AG-PRO+NBY.png','353.42','2025-03-05 16:04:48.213751','2025-03-05 16:04:48.213751','basketball','women'),
	 ('8b7be414-16f5-4e00-bc8f-d1d933e147c3','Nike Mercurial Superfly 10 Elite By You','{"benefits":[{"header":"Ultimate Agility","body":["The Mercurial Superfly 10 Elite is engineered for explosive acceleration and unmatched agility on the pitch."]},{"header":"Superior Ball Feel","body":["Revolutionary upper material provides exceptional touch and control, enabling you to dominate the game."]},{"header":"Locked-In Fit","body":["Dynamic Fit collar creates a seamless, sock-like fit, providing enhanced support and stability."]}],"product_details":[{"header":"Product Details","body":["Firm-ground (FG) cleats for use on short-grass fields","High-tenacity yarns to make this upper soft while providing the support needed for 90 minutes.","Tri-star studs provide multi-directional traction, so you can change directions quickly and confidently.","By You customization options available","Product Code: DV4337-001 (Example Product Code, Replace with Actual if available)"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e7239159-c97b-42e6-93a7-38e2ef73187c/ZM+SUPERFLY+10+ELITE+FG+NBY.png','475.39','2025-03-05 16:04:48.214423','2025-03-05 16:04:48.214423','football','women'),
	 ('87a7ba9f-9879-4bd4-bc32-b05c5737abe6','Nike Mercurial Superfly 10 Elite By You','{"benefits":[{"header":"Explosive Speed and Agility","body":["Experience unparalleled acceleration with the innovative Zoom Air unit, specifically engineered for explosive responsiveness on the pitch. The tri-star stud pattern ensures exceptional grip and multi-directional movement, letting you cut and sprint with confidence."]},{"header":"Customizable Comfort and Fit","body":["The Flyknit upper molds to your foot for a secure, sock-like fit, providing optimal comfort and support throughout the game. With Nike By You, personalize your cleat with colors and designs that reflect your unique style."]}],"product_details":[{"header":"Product Details","body":["For use on firm-ground surfaces","Dynamic Fit collar for enhanced ankle support","Zoom Air unit for responsive cushioning","Flyknit upper construction","Style: Nike Mercurial Superfly 10 Elite By You"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/e7239159-c97b-42e6-93a7-38e2ef73187c/ZM+SUPERFLY+10+ELITE+FG+NBY.png','463.93','2025-03-05 16:04:48.215233','2025-03-05 16:04:48.215233','football','women'),
	 ('3973dcc6-fb0e-45df-a6b5-3ee7018634fd','Nike Mercurial Superfly 10 Elite By You','{"benefits":[{"header":"Unleash Your Speed","body":["Dominate the field with the innovative Zoom Air unit in the heel, providing responsive cushioning for explosive acceleration and quick cuts. The strategically placed studs deliver exceptional traction, allowing you to maintain control at top speed."]},{"header":"Personalized Style and Comfort","body":["Experience a secure, sock-like fit with the Flyknit upper that conforms to your foot. The Nike By You customization options allow you to express your individuality and create a cleat that''s uniquely yours."]}],"product_details":[{"header":"Product Details","body":["Designed for firm-ground surfaces","Dynamic Fit collar for a seamless fit","Zoom Air unit for responsive cushioning","Flyknit construction for lightweight support","Style: Nike Mercurial Superfly 10 Elite By You"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/203982c8-55c7-4a33-af6a-fd3ec71a67f6/ZM+SUPERFLY+10+ELITE+FG+NBY.png','273.92','2025-03-05 16:04:48.216046','2025-03-05 16:04:48.216046','gym_and_training','women');
INSERT INTO public."PRODUCT" ("PRODUCT_ID","PRODUCT_NAME","PRODUCT_DESCRIPTION","PRODUCT_IMAGE","PRODUCT_PRICE","CREATED_AT","UPDATED_AT","PRODUCT_CATEGORY","GENDER") VALUES
	 ('04d13294-c1d6-4706-9077-4b161bb6edec','Nike Mercurial Vapor 16 Academy By You','{"benefits":[{"header":"Explosive Acceleration","body":["The Zoom Air unit under the heel provides responsive cushioning to propel you forward with every step. Experience unparalleled speed and agility on the pitch, leaving defenders in your wake."]},{"header":"Optimal Touch and Control","body":["A synthetic leather upper with strategically placed texturing enhances ball control, allowing for precise dribbling and accurate passing. Confidently dictate the game with superior touch and feel."]}],"product_details":[{"header":"Product Details","body":["For use on firm-ground surfaces","Zoom Air unit in the heel","Synthetic leather upper for enhanced ball control","Conical studs for optimal traction","Style: Nike Mercurial Vapor 16 Academy By You"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/4a78675b-dca5-459e-9d63-25d44d69ab2c/ZM+VAPOR+16+ACADEMY+FG+NBY.png','237.24','2025-03-05 16:04:48.217037','2025-03-05 16:04:48.217037','football','women'),
	 ('72c92df1-e3d8-484c-8fe8-7c5f105b697b','Nike Mercurial Superfly 10 Academy By You','{"benefits":[{"header":"Dynamic Fit and Lockdown","body":["The Dynamic Fit collar wraps your ankle for a secure, locked-in feel, providing enhanced support and stability during quick cuts and turns. Experience confident movement on the field without distractions."]},{"header":"Responsive Cushioning and Grip","body":["The Zoom Air unit in the heel delivers responsive cushioning, propelling you forward with every step. The aggressive stud pattern ensures optimal traction on firm-ground surfaces."]}],"product_details":[{"header":"Product Details","body":["Designed for firm-ground play","Dynamic Fit collar for a secure fit","Zoom Air unit for responsive cushioning","Synthetic upper for durability","Style: Nike Mercurial Superfly 10 Academy By You"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/0a92b637-3f7b-4064-a3f9-530a2d8e581c/ZM+SUPERFLY+10+ACADEMY+FG+NBY.png','384.70','2025-03-05 16:04:48.218157','2025-03-05 16:04:48.218157','football','women'),
	 ('2f30be69-f22e-4198-8692-6ca34a2866ce','Nike Mercurial Superfly 10 Academy By You','{"benefits":[{"header":"Explosive Speed and Support","body":["Experience the explosive power of the Zoom Air unit, engineered for responsive cushioning and rapid acceleration. The Dynamic Fit collar provides a secure, supportive fit around your ankle, allowing for confident movement."]},{"header":"Enhanced Touch and Control","body":["The synthetic upper features strategically placed texturing for enhanced ball control and precision passing. Dominate the game with improved touch and feel on the ball."]}],"product_details":[{"header":"Product Details","body":["Optimized for firm-ground surfaces","Dynamic Fit collar for a locked-in feel","Zoom Air unit for responsive cushioning","Synthetic leather upper","Style: Nike Mercurial Superfly 10 Academy By You"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/0e792c4e-d434-43ae-a8df-baf70e60059a/ZM+SUPERFLY+10+ACADEMY+FG+NBY.png','457.86','2025-03-05 16:04:48.219561','2025-03-05 16:04:48.219561','football','women'),
	 ('e85d102d-5d4d-45c3-948f-597d854b11cd','Nike Mercurial Vapor 16 Elite By You','{"benefits":[{"header":"Unleash Your Potential","body":["Experience explosive speed and agility with the Zoom Air unit, specifically engineered for responsive cushioning. The innovative stud pattern provides exceptional traction, allowing you to accelerate and change direction with confidence."]},{"header":"Ultimate Comfort and Control","body":["The Flyknit upper wraps your foot in a secure, sock-like fit, providing optimal comfort and support. The strategically placed texturing enhances ball control for precise dribbling and passing."]}],"product_details":[{"header":"Product Details","body":["Designed for use on firm-ground pitches","Flyknit upper for a snug, supportive fit","Zoom Air unit for responsive cushioning","Aggressive stud configuration for optimal traction","Style: Nike Mercurial Vapor 16 Elite By You"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/bd72a15c-c866-44cf-9290-cb890f3a358c/ZM+VAPOR+16+ELITE+FG+NBY.png','389.13','2025-03-05 16:04:48.221029','2025-03-05 16:04:48.221029','football','women'),
	 ('070f7904-c7eb-4af3-8b39-30819ce6ce92','Nike Mercurial Vapor 16 Elite By You','{"benefits":[{"header":"Elite Performance on Artificial Grass","body":["Designed specifically for artificial grass surfaces, the AG-PRO plate provides exceptional grip and stability for quick cuts and turns. The Zoom Air unit delivers responsive cushioning for lasting comfort."]},{"header":"Seamless Fit and Enhanced Touch","body":["The Flyknit upper conforms to your foot for a secure, sock-like fit, while the strategically placed texturing enhances ball control. Experience ultimate comfort and precision on the pitch."]}],"product_details":[{"header":"Product Details","body":["Optimized for artificial grass (AG) surfaces","Flyknit construction for a lightweight, adaptive fit","Zoom Air unit for responsive cushioning","AG-PRO plate for enhanced traction","Style: Nike Mercurial Vapor 16 Elite AG-PRO By You"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/8d7aaeeb-ee68-42d4-baf9-6c3927a32f93/ZM+VAPOR+16+ELITE+AG-PRO+NBY.png','332.20','2025-03-05 16:04:48.221949','2025-03-05 16:04:48.221949','football','women'),
	 ('a8c2f2d0-b0f2-4d48-8b85-576a880e439e','Nike Phantom Luna 2 Academy By You','{"benefits":[{"header":"Precision and Comfort","body":["Experience enhanced comfort with a soft, flexible upper that minimizes distractions during play. The strategically placed studs provide optimal traction on both firm-ground and multi-ground surfaces, allowing for agile movements."]},{"header":"Enhanced Control and Stability","body":["The asymmetrical lacing system expands the ball contact area for precise passing and shooting. A supportive plate helps maintain stability and balance, empowering you to control the game."]}],"product_details":[{"header":"Product Details","body":["Suitable for firm-ground (FG) and multi-ground (MG) surfaces","Asymmetrical lacing system","Soft synthetic upper for enhanced comfort","Conical and bladed studs for versatile traction","Style: Nike Phantom Luna 2 Academy By You"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/56a172c2-57e7-45e7-8687-016947f5459d/PHANTOM+LUNA+II+ACAD+FG%2FMG+NBY.png','464.89','2025-03-05 16:04:48.223072','2025-03-05 16:04:48.223072','football','women'),
	 ('48c27bef-50bb-435d-a320-ab36936dc185','Nike Phantom Luna 2 Elite By You','{"benefits":[{"header":"Elite Touch and Control","body":["Dominate the pitch with the revolutionary touch zone, providing exceptional grip and control in all weather conditions. The soft and flexible upper conforms to your foot for a personalized fit and enhanced comfort."]},{"header":"Explosive Agility and Stability","body":["The agile plate is designed to provide instant responsiveness, allowing for quick cuts and turns with confidence. The strategically placed studs deliver optimal traction on firm-ground surfaces."]}],"product_details":[{"header":"Product Details","body":["For use on firm-ground surfaces","Revolutionary touch zone for enhanced ball control","Flyknit upper for a seamless, sock-like fit","Agile plate for instant responsiveness","Style: Nike Phantom Luna 2 Elite By You"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/b4b99ec1-4bef-4cd7-8f6c-f3b8740d1db9/PHANTOM+LUNA+II+ELITE+FG+NBY.png','462.31','2025-03-05 16:04:48.22389','2025-03-05 16:04:48.22389','basketball','women'),
	 ('dcc02c11-dd73-4b4a-ac7a-e50489935d6c','Nike React Gato','{"benefits":[{"header":"Responsive Cushioning","body":["Experience exceptional comfort and energy return with Nike React foam. Designed for small-sided games, this technology keeps you fresh and focused throughout the match."]},{"header":"Enhanced Ball Control","body":["The Flyknit construction delivers a close, comfortable fit that enhances your touch on the ball. Control the game with precision and confidence."]}],"product_details":[{"header":"Product Details","body":["Nike React foam midsole","Flyknit upper construction","Non-marking outsole","Designed for indoor court surfaces","Style: Nike React Gato"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/579d3fe1-6a26-4d2b-b31d-1502ea6ee832/NIKE+REACTGATO.png','299.54','2025-03-05 16:04:48.224598','2025-03-05 16:04:48.224598','gym_and_training','women'),
	 ('2f1b6467-1e0a-4e3e-8f73-e049fe379aac','Nike Phantom Luna 2 Club','{"benefits":[{"header":"Turf Traction","body":["Dominate on artificial turf surfaces with a durable outsole designed for optimal grip and agility. Make quick cuts and turns with confidence, leaving your opponents in the dust."]},{"header":"Comfortable Fit","body":["The soft, synthetic upper provides a comfortable and supportive fit, allowing you to focus on your game. Play with confidence and precision, knowing your footwear will keep you comfortable."]}],"product_details":[{"header":"Product Details","body":["Designed for artificial turf surfaces","Soft synthetic upper","Turf outsole for optimal traction","Cushioned insole","Style: Nike Phantom Luna 2 Club"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/99d8ac31-15fe-4bfb-885d-b047e84b3380/PHANTOM+LUNA+II+CLUB+TF.png','477.96','2025-03-05 16:04:48.225287','2025-03-05 16:04:48.225287','gym_and_training','women'),
	 ('66a62aab-a4b9-42a8-b395-ffa6cb0de8b2','Nike Phantom GX 2 Club','{"benefits":[{"header":"Superior Turf Grip","body":["Engineered for artificial turf, the outsole provides exceptional traction, allowing for quick pivots and explosive movements. Maintain control and dominate the small-sided game."]},{"header":"Comfortable and Responsive Feel","body":["The soft synthetic upper provides a comfortable, adaptive fit, while the cushioned insole delivers all-day support. Experience enhanced ball control and a responsive feel with every touch."]}],"product_details":[{"header":"Product Details","body":["Designed for artificial turf surfaces","Soft synthetic upper for enhanced comfort","Turf outsole for superior grip","Cushioned insole for all-day comfort","Style: Nike Phantom GX 2 Club"]}]}','https://static.nike.com/a/images/c_limit,w_592,f_auto/t_product_v1/f9dbcd15-5356-4ede-bdec-f35d2de95050/PHANTOM+GX+II+CLUB+TF.png','280.89','2025-03-05 16:04:48.226124','2025-03-05 16:04:48.226124','football','women');
